/* ============================================================
   i18n.js —— 站点双语层(中文 / English)
   · 新用户第一次进入网站时弹出语言选择框,选择框文案本身是双语的;
   · 语言记在 localStorage['siteLang'],各页面共用,切换入口在「设置 → 更多」;
   · 角色卡的人设提示词不做「替换式英化」:中文原文始终保留。
     选择 English 后打开角色卡,会询问是否用「你自己配置的 API」翻译成英文,
     译文与中文原文并存显示,并缓存在本机 localStorage。
   · DICT 为界面文案字典,页面元素加 data-i18n="键名" 即可随语言切换。
   · PHRASES 为「整段文本节点替换」短语表;大量界面短语的补全集中在
     本文件末尾,通过 SiteI18n.addPhrases() 分批注册(可继续追加新词条)。
 */
(function () {
    'use strict';

    var LANG_KEY = 'siteLang';
    var WELCOME_SEEN_KEY = 'myswWelcomeSeen_v1';   // 与 first-run-guide.js 保持一致
    var CACHE_PREFIX = 'cardTranslation_v1:';
    var CHUNK_CHARS = 2500;                        // 单次请求的最大字符数
    var STYLE_ID = 'si18n-style';

    var DICT = {
        zh: {
            'switch.toEn': 'English',
            'switch.toZh': '中文',
            'card.askTitle': '翻译成英文?',
            'card.askMsg': '这张角色卡的设定是中文原文。\n是否使用你在「AI 配置」里填写的 API,把它翻译成英文?\n中文原文会保留,英文译文显示在它下方,并缓存在本机。\n(会消耗你所配置 API 的额度)',
            'card.askOk': '翻译',
            'card.askCancel': '暂不',
            'card.noApi': '还没有配置 API:请先在主站「设置 → AI 配置」里填写 API 地址与 Key。',
            'card.translateBtn': '用我的 API 翻译成英文',
            'card.retranslate': '重新翻译',
            'card.progress': '正在翻译… 第 {n}/{total} 段',
            'card.failed': '翻译失败:',
            'card.enTitle': 'English 译文(AI 生成)',
            'card.enHint': '译文由你配置的 API 生成,仅供阅读;以中文原文为准。',
            'card.enName': '角色名',
            'card.enPrompt': '人设提示词',
            'card.enWelcome': '开场白',
            'card.applyPrompt': '用英文替换角色提示词',
            'card.applyWelcome': '用英文替换开场白',
            'card.applyDone': '已替换「角色提示词」,点「保存修改」后生效',
            'card.applyDoneWelcome': '已替换「开场白」,点「保存修改」后生效',
            'card.applyNoTarget': '当前没有可写入的角色编辑框:请先打开该角色的编辑窗口再替换',
            'card.applyTitle': 'English 译文'
        },
        en: {
            'switch.toEn': 'English',
            'switch.toZh': '中文',
            'card.askTitle': 'Translate to English?',
            'card.askMsg': 'This character card is written in Chinese. Translate it to English using the API you configured in AI settings?\nThe Chinese original is kept; the English version appears below it and is cached on this device.\n(This uses your API quota.)',
            'card.askOk': 'Translate',
            'card.askCancel': 'Not now',
            'card.noApi': 'No API configured yet. Please fill in the API URL and key under Settings → AI config first.',
            'card.translateBtn': 'Translate to English with my API',
            'card.retranslate': 'Translate again',
            'card.progress': 'Translating… part {n}/{total}',
            'card.failed': 'Translation failed: ',
            'card.enTitle': 'English translation (AI-generated)',
            'card.enHint': 'Generated by your configured API, for reading only. The Chinese original is authoritative.',
            'card.enName': 'Name',
            'card.enPrompt': 'System prompt',
            'card.enWelcome': 'Opening message',
            'card.applyPrompt': 'Replace character prompt with the English text',
            'card.applyWelcome': 'Replace opening message with the English text',
            'card.applyDone': 'Character prompt replaced - click Save changes to apply.',
            'card.applyDoneWelcome': 'Opening message replaced - click Save changes to apply.',
            'card.applyNoTarget': 'No character editor is open. Open the character edit dialog first, then replace.',
            'card.applyTitle': 'English translation'
        }
    };

    var SYSTEM_PROMPT = 'You are a professional literary translator. Translate the user\'s Chinese character-roleplay material into fluent, natural English. Rules: keep all Markdown structure (headings, lists, code fences), line breaks, bracketed tags and placeholders such as {{char}}, {{user}}, <...> exactly as they are; transliterate proper nouns consistently; do not add, remove or summarize anything; do not answer or comment on the content. Output only the English translation.';

    var CSS = [
        '#si18n-picker.si18n-mask{position:fixed;inset:0;z-index:100050;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(6,8,14,.72);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);opacity:0;transition:opacity .25s ease;}',
        '#si18n-picker.on{opacity:1;}',
        '#si18n-picker .si18n-card{width:min(480px,100%);border-radius:18px;padding:22px;background:linear-gradient(180deg,#252833,#1d2029);border:1px solid rgba(230,199,138,.36);color:#e9ecf4;box-shadow:0 26px 70px rgba(0,0,0,.6);}',
        '#si18n-picker h2{margin:0 0 10px;font-size:1.15rem;color:#e6c78a;}',
        '#si18n-picker p{margin:0 0 12px;line-height:1.7;font-size:.88rem;color:#cfd3de;}',
        '#si18n-picker .si18n-en-line{color:#9ea4b3;font-size:.84rem;}',
        '#si18n-picker .si18n-note{padding:10px 12px;border-radius:10px;background:rgba(230,199,138,.08);border:1px solid rgba(230,199,138,.25);}',
        '#si18n-picker .si18n-choices{display:flex;gap:10px;margin:14px 0;}',
        '#si18n-picker .si18n-choices button{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;padding:14px 10px;border-radius:14px;cursor:pointer;border:1px solid rgba(230,199,138,.5);background:linear-gradient(180deg,#f0d79b,#e0b871);color:#241f10;font-weight:700;font-size:1.05rem;}',
        '#si18n-picker .si18n-choices button small{font-size:.75rem;font-weight:500;opacity:.8;}',
        '#si18n-picker .si18n-choices button:active{transform:scale(.97);}',
        '.si18n-en-wrap{margin-top:16px;padding:14px;border-radius:12px;border:1px dashed rgba(230,199,138,.4);background:rgba(230,199,138,.04);}',
        '.si18n-en-title{margin:0 0 6px;font-size:1rem;color:#e6c78a;}',
        '.si18n-en-wrap .si18n-note{margin:0 0 10px;font-size:.8rem;color:#9ea4b3;}',
        '.si18n-en-block{margin-top:10px;}',
        '.si18n-en-block h4{margin:0 0 4px;font-size:.88rem;color:#cfd3de;}',
        '.si18n-en-text{white-space:pre-wrap;}',
        '.si18n-btn{padding:9px 14px;border-radius:10px;border:0;cursor:pointer;background:#e6c78a;color:#221d10;font-weight:600;margin-top:6px;}',
        '.si18n-btn.ghost{background:transparent;border:1px solid #e6c78a;color:#e6c78a;}',
        '.si18n-status{color:#e6c78a;font-size:.88rem;}',
        '.si18n-note-warn{color:#f0a878;font-size:.85rem;}',
        '.si18n-btn + .si18n-btn{margin-left:8px;}'
    ].join('');

    function safeGet(key) { try { return localStorage.getItem(key); } catch (e) { return null; } }

    function readLang() {
        var v = safeGet(LANG_KEY);
        return (v === 'zh' || v === 'en') ? v : '';
    }

    var current = readLang() || 'zh';
    // 新用户判定:从未选过语言,且从未关闭过首次欢迎框
    // 只对「明显的新用户」弹语言框:没选过语言、没看过欢迎页、没配过 API、没建过角色、没有聊天线程。
    // 【注意】apiEndpoints / aiChatSettings / threadManager_v2 这几个 key 在启动流程里
    // 会被自动写入「空壳」数据(endpoints.js 的 read() 会物化空站点库、main.js 会落盘空线程),
    // 所以不能只判 key 是否存在,必须看内容——否则判定结果取决于脚本执行顺序,时序脆弱。
    function jsonGet(key) {
        try { var raw = safeGet(key); return raw ? JSON.parse(raw) : null; } catch (e) { return null; }
    }
    function apiStoreConfigured() {
        var d = jsonGet('apiEndpoints');
        if (!d) return false;
        if (!Array.isArray(d.sites)) return false; // 空壳/坏数据都视为未配置
        return d.sites.some(function (s) { return String((s && s.url) || '').trim() || String((s && s.key) || '').trim(); });
    }
    function aiChatConfigured() {
        var d = jsonGet('aiChatSettings');
        return !!(d && (String(d.apiUrl || '').trim() || String(d.apiKey || '').trim()));
    }
    function threadsConfigured() {
        var d = jsonGet('threadManager_v2');
        if (!d || typeof d !== 'object') return false;
        return Object.values(d).some(function (f) {
            return Array.isArray(f && f.threads) && f.threads.some(function (th) { return Array.isArray(th && th.messages) && th.messages.length; });
        });
    }
    function rolesConfigured() {
        var d = jsonGet('customFriendsData');
        return !!(d && typeof d === 'object' && Object.keys(d).length);
    }
    var pickerPending = !readLang() && !safeGet(WELCOME_SEEN_KEY) &&
        !apiStoreConfigured() && !aiChatConfigured() && !threadsConfigured() && !rolesConfigured();
    var afterCbs = [];

    function t(key) {
        var d = DICT[current] || DICT.zh;
        if (d[key] != null) return d[key];
        return DICT.zh[key] != null ? DICT.zh[key] : key;
    }

    function fill(str, vars) {
        return String(str).replace(/\{(\w+)\}/g, function (_, k) { return vars && vars[k] != null ? vars[k] : ''; });
    }

    function el(tag, cls, text) {
        var n = document.createElement(tag);
        if (cls) n.className = cls;
        if (text != null) n.textContent = text;
        return n;
    }

    function injectStyle() {
        if (document.getElementById(STYLE_ID)) return;
        var s = document.createElement('style');
        s.id = STYLE_ID;
        s.textContent = CSS;
        document.head.appendChild(s);
    }

    function hash(str) {
        var h = 5381;
        str = String(str || '');
        for (var i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
        return (h >>> 0).toString(36);
    }

    /* ---------------- 语言状态 ---------------- */

    /* 浏览器标签页标题:<title> 在 <head> 里,不在 body 的短语扫描范围内,
       这里单独按 PHRASES 精确匹配翻译;未收录的标题保持原文。 */
    var TITLE_ORIG = null;
    function applyDocTitle() {
        if (TITLE_ORIG === null) TITLE_ORIG = document.title || '';
        var key = TITLE_ORIG.trim();
        document.title = (current === 'en' && Object.prototype.hasOwnProperty.call(PHRASES, key)) ? PHRASES[key] : TITLE_ORIG;
    }

    /* ---------------- 文档整块英文化 ----------------
       键 = 元素原始中文文本（空白归一化后逐字一致），值 = 整段英文 HTML。
       命中就整块换掉 innerHTML，切回中文时原样还原。 */
    var docsSwapped = [];
    var DOCS_BLOCK_SEL = 'h1,h2,h3,h4,p,li,td,th,dt,dd,figcaption,summary,.info-card-title,.field-name,.field-desc';

    function docsBlockKey(el) {
        return String(el.textContent || '').replace(/\s+/g, ' ').trim();
    }

    function swapBlock(el, en) {
        if (el.getAttribute('data-endone') === '1') return;
        if (typeof en !== 'string' || !en) return;
        el.__zhHTML = el.innerHTML;
        el.innerHTML = en;
        el.setAttribute('data-endone', '1');
        docsSwapped.push(el);
    }

    function applyDocsEn() {
        if (current !== 'en' || !window.DOCS_EN) { restoreDocsZh(); return; }
        var main = document.querySelector('.docs-main');
        if (main) {
            Array.prototype.forEach.call(main.querySelectorAll(DOCS_BLOCK_SEL), function (el) {
                // 容器里还套着别的块（嵌套 li / 单元格里的列表）时跳过，避免把子块一起吞掉
                if (el.querySelector('li,p,td,th,div,ul,ol')) return;
                swapBlock(el, window.DOCS_EN[docsBlockKey(el)]);
            });
        }
        /* 目录另走一趟：只换 <a> 的文字，别用整块替换，
           否则带子目录的 <li> 一换就把链接本身吃掉。 */
        Array.prototype.forEach.call(document.querySelectorAll('.docs-toc a'), function (a) {
            swapBlock(a, window.DOCS_EN[docsBlockKey(a)]);
        });
    }

    function restoreDocsZh() {
        while (docsSwapped.length) {
            var el = docsSwapped.pop();
            if (typeof el.__zhHTML === 'string') el.innerHTML = el.__zhHTML;
            el.removeAttribute('data-endone');
        }
    }

    function applyDom() {
        document.documentElement.setAttribute('lang', current === 'en' ? 'en' : 'zh-CN');
        document.querySelectorAll('[data-i18n]').forEach(function (node) {
            node.textContent = t(node.getAttribute('data-i18n'));
        });
        applyDocsEn();
        applyPhrases(document.body);
        applyDocTitle();
        syncLangButtons();
    }

    function setLang(lang) {
        if (lang !== 'zh' && lang !== 'en') return;
        current = lang;
        try { localStorage.setItem(LANG_KEY, lang); } catch (e) { /* 忽略 */ }
        applyDom();
        try { window.dispatchEvent(new CustomEvent('sitelangchange', { detail: { lang: lang } })); } catch (e) { /* 忽略 */ }
    }

    /* ---------------- 首次语言选择框(双语文案) ---------------- */

    function afterPicker(cb) {
        if (pickerPending) afterCbs.push(cb);
        else cb();
    }

    function closePicker() {
        pickerPending = false;
        var node = document.getElementById('si18n-picker');
        if (node) {
            node.classList.remove('on');
            setTimeout(function () { node.remove(); }, 250);
        }
        afterCbs.splice(0).forEach(function (cb) { try { cb(); } catch (e) { /* 忽略 */ } });
    }

    function showPicker() {
        if (window.__myswUserSpace) return; // 用户代码空间页面里不弹主站的语言选择框
        if (document.getElementById('si18n-picker')) return;
        var wrap = document.createElement('div');
        wrap.id = 'si18n-picker';
        wrap.className = 'si18n-mask';
        wrap.setAttribute('role', 'dialog');
        wrap.setAttribute('aria-modal', 'true');
        wrap.innerHTML = [
            '<div class="si18n-card">',
            '<h2><i class="ri-translate-2"></i> 选择语言 · Choose your language</h2>',
            '<p>请选择界面语言,之后可以在「设置 → 更多」里随时切换。<br><span class="si18n-en-line">Please choose your interface language. You can switch any time in Settings → More.</span></p>',
            '<div class="si18n-choices">',
            '<button type="button" data-si18n-pick="zh">中文<small>Chinese</small></button>',
            '<button type="button" data-si18n-pick="en">English<small>英文</small></button>',
            '</div>',
            '<p class="si18n-note">角色卡的人设提示词保持中文原文,不会被替换。选择 English 后,打开角色卡时可以用你自己配置的 API 把它翻译成英文,中英文并存显示。<br><span class="si18n-en-line">Character prompts stay in their original Chinese. With English selected, you can translate a card with your own API when you open it; Chinese and English are shown side by side.</span></p>',
            '</div>'
        ].join('');
        document.body.appendChild(wrap);
        requestAnimationFrame(function () { wrap.classList.add('on'); });
        wrap.addEventListener('click', function (event) {
            var btn = event.target && event.target.closest ? event.target.closest('[data-si18n-pick]') : null;
            if (!btn) return;
            setLang(btn.getAttribute('data-si18n-pick'));
            closePicker();
        });
    }

    /* ---------------- 角色卡 AI 翻译(用户自己的 API) ---------------- */

    function getApi() {
        try {
            if (window.EndpointStore && typeof EndpointStore.getEffectiveApiSettings === 'function') {
                return EndpointStore.getEffectiveApiSettings() || {};
            }
        } catch (e) { /* 回退 */ }
        try { return JSON.parse(localStorage.getItem('aiChatSettings') || '{}') || {}; } catch (e) { return {}; }
    }

    function hasApi(api) { return !!(api && api.apiUrl && api.apiKey); }

    /** 按空行/换行切成不超过 max 字符的段 */
    function chunkText(text, max) {
        var out = [];
        var buf = '';
        String(text || '').split('\n').forEach(function (line) {
            while (line.length > max) {
                if (buf) { out.push(buf); buf = ''; }
                out.push(line.slice(0, max));
                line = line.slice(max);
            }
            if (buf && buf.length + line.length + 1 > max) { out.push(buf); buf = ''; }
            buf = buf ? buf + '\n' + line : line;
        });
        if (buf) out.push(buf);
        return out;
    }

    function translateCard(card, onStep) {
        var api = getApi();
        if (!hasApi(api)) return Promise.reject(new Error(t('card.noApi')));
        if (!window.ApiModule || typeof window.ApiModule.requestSmallTask !== 'function') {
            return Promise.reject(new Error('ApiModule 尚未就绪'));
        }
        var plan = [
            { field: 'name', parts: [String(card.name || '')] },
            { field: 'systemPrompt', parts: chunkText(card.systemPrompt, CHUNK_CHARS) },
            { field: 'welcomeMessage', parts: chunkText(card.welcomeMessage, CHUNK_CHARS) }
        ];
        var jobs = [];
        plan.forEach(function (p) {
            p.parts.forEach(function (text) { if (text.trim()) jobs.push({ field: p.field, text: text }); });
        });
        var out = { name: '', systemPrompt: [], welcomeMessage: [] };
        return jobs.reduce(function (chain, job, i) {
            return chain.then(function () {
                if (onStep) onStep(i + 1, jobs.length);
                return window.ApiModule.requestSmallTask(api, SYSTEM_PROMPT, job.text, { maxTokens: 4096, temperature: 0.3, label: '角色卡翻译' })
                    .then(function (res) {
                        var s = String(res || '').trim();
                        if (job.field === 'name') out.name = s; else out[job.field].push(s);
                    });
            });
        }, Promise.resolve()).then(function () {
            return {
                name: out.name,
                systemPrompt: out.systemPrompt.join('\n'),
                welcomeMessage: out.welcomeMessage.join('\n'),
                model: api.model || '',
                at: Date.now()
            };
        });
    }

    function cacheKey(card) {
        return CACHE_PREFIX + card.id + ':' + hash(String(card.systemPrompt || '') + '\u0001' + String(card.welcomeMessage || ''));
    }
    function readCache(card) {
        try { var raw = localStorage.getItem(cacheKey(card)); return raw ? JSON.parse(raw) : null; } catch (e) { return null; }
    }
    function writeCache(card, data) {
        try { localStorage.setItem(cacheKey(card), JSON.stringify(data)); } catch (e) { /* 配额不足时只是不缓存 */ }
    }

    function block(label, text) {
        var wrap = el('div', 'si18n-en-block');
        wrap.appendChild(el('h4', '', label));
        wrap.appendChild(el('div', 'market-preview si18n-en-text', text || ''));
        return wrap;
    }

    function renderPrompt(box, card, note) {
        box.innerHTML = '';
        var wrap = el('div', 'si18n-en-wrap');
        if (note) wrap.appendChild(el('p', 'si18n-note-warn', note));
        var btn = el('button', 'si18n-btn', t('card.translateBtn'));
        btn.type = 'button';
        btn.addEventListener('click', function () { runTranslate(box, card); });
        wrap.appendChild(btn);
        box.appendChild(wrap);
    }

    function renderTranslation(box, card, data) {
        box.innerHTML = '';
        var wrap = el('div', 'si18n-en-wrap');
        wrap.appendChild(el('h3', 'si18n-en-title', t('card.enTitle')));
        wrap.appendChild(el('p', 'si18n-note', t('card.enHint')));
        wrap.appendChild(block(t('card.enName'), data.name));
        wrap.appendChild(block(t('card.enPrompt'), data.systemPrompt));
        if (data.welcomeMessage) wrap.appendChild(block(t('card.enWelcome'), data.welcomeMessage));
        // 「直接替换」:把英文译文一键写回角色编辑框(仅当页面上存在编辑框时提供,
        // 如主站的角色编辑弹窗;角色卡市场是只读页,不显示这两个按钮)。
        var hasEditor = !!(document.getElementById('new-char-prompt-modal') || document.getElementById('new-char-prompt'));
        if (hasEditor && String(data.systemPrompt || '').trim()) {
            var applyPromptBtn = el('button', 'si18n-btn', t('card.applyPrompt'));
            applyPromptBtn.type = 'button';
            applyPromptBtn.addEventListener('click', function () { applyTranslation(card, data, 'prompt'); });
            wrap.appendChild(applyPromptBtn);
        }
        if (hasEditor && String(data.welcomeMessage || '').trim()) {
            var applyWelcomeBtn = el('button', 'si18n-btn ghost', t('card.applyWelcome'));
            applyWelcomeBtn.type = 'button';
            applyWelcomeBtn.addEventListener('click', function () { applyTranslation(card, data, 'welcome'); });
            wrap.appendChild(applyWelcomeBtn);
        }
        var again = el('button', 'si18n-btn ghost', t('card.retranslate'));
        again.type = 'button';
        again.addEventListener('click', function () { runTranslate(box, card); });
        wrap.appendChild(again);
        box.appendChild(wrap);
    }

    function runTranslate(box, card) {
        if (!hasApi(getApi())) { renderPrompt(box, card, t('card.noApi')); return; }
        box.innerHTML = '';
        var status = el('p', 'si18n-status', '…');
        box.appendChild(status);
        translateCard(card, function (n, total) {
            status.textContent = fill(t('card.progress'), { n: n, total: total });
        }).then(function (data) {
            writeCache(card, data);
            renderTranslation(box, card, data);
        }).catch(function (err) {
            renderPrompt(box, card, t('card.failed') + (err && err.message ? err.message : String(err)));
        });
    }

    /** 轻量提示：主站用 showToast,其它页面退回站内对话框 */
    function notify(msg) {
        try { if (typeof window.showToast === 'function') { window.showToast(msg, 'ri-translate-2'); return; } } catch (e) { /* 继续兜底 */ }
        try { if (window.Dlg && typeof window.Dlg.alert === 'function') { window.Dlg.alert({ title: t('card.applyTitle'), message: msg }); return; } } catch (e) { /* 继续兜底 */ }
        try { console.log('[SiteI18n]', msg); } catch (e) { /* 忽略 */ }
    }

    /**
     * 用英文译文直接替换角色编辑框里的内容(提示词 / 开场白)。
     * 只写输入框、不落库:用户点「保存修改 / 创建角色」后才真正生效,
     * 不保存直接关闭就还是中文原文,不会误覆盖角色卡。
     */
    function applyTranslation(card, data, kind) {
        var isWelcome = kind === 'welcome';
        var ta = isWelcome
            ? (document.getElementById('new-char-welcome-modal') || document.getElementById('new-char-welcome'))
            : (document.getElementById('new-char-prompt-modal') || document.getElementById('new-char-prompt'));
        var text = String(isWelcome ? (data.welcomeMessage || '') : (data.systemPrompt || '')).trim();
        if (!ta || !text) { notify(t('card.applyNoTarget')); return; }
        ta.value = text;
        ta.dispatchEvent(new Event('input', { bubbles: true }));
        ta.dispatchEvent(new Event('change', { bubbles: true }));
        notify(t(isWelcome ? 'card.applyDoneWelcome' : 'card.applyDone'));
    }

    function askTranslate() {
        var D = window.Dlg;
        if (D && typeof D.confirm === 'function') {
            return Promise.resolve(D.confirm({
                title: t('card.askTitle'),
                message: t('card.askMsg'),
                okText: t('card.askOk'),
                cancelText: t('card.askCancel')
            }));
        }
        return Promise.resolve(window.confirm(t('card.askTitle') + '\n\n' + t('card.askMsg')));
    }

    /**
     * 角色卡详情里挂载英文译文区(中文原文保留在上方,英文并存在下方)。
     * 仅在 English 模式下生效;已有缓存则直接展示,否则弹窗询问是否翻译。
     */
    function attachCardTranslate(containerId, card) {
        var box = document.getElementById(containerId);
        if (!box) return;
        box.innerHTML = '';
        if (current !== 'en' || !card) return;
        var cached = readCache(card);
        if (cached) { renderTranslation(box, card, cached); return; }
        if (!hasApi(getApi())) { renderPrompt(box, card, t('card.noApi')); return; }
        renderPrompt(box, card, '');
        askTranslate().then(function (yes) { if (yes) runTranslate(box, card); });
    }

    /* ---------------- 界面短语替换(中文 → English) ----------------
       只处理「整段文字完全等于下表左侧」的文本节点与 placeholder / title / aria-label。
       切回中文时用记录的原文还原;动态渲染的新节点由 MutationObserver 重新处理。 */

    var PHRASES = {
        '短信': 'Messages', '论坛': 'Forum', '插件市场': 'Plugin Market', '文档': 'Docs',
        '角色卡市场': 'Character Market', '我的角色': 'My Characters', '分组管理': 'Groups',
        '设置': 'Settings', '查看设定': 'View details', '添加到主站': 'Add to main site',
        '移出主站': 'Remove from main site', '全选': 'Select all', '取消选择': 'Clear selection',
        '确定': 'OK', '取消': 'Cancel', '保存修改': 'Save changes', '创建角色': 'Create character',
        '删除': 'Delete', '新建分组': 'New group', '恢复移出': 'Restore removed',
        '自制角色卡': 'Create my own card', '全部来源': 'All sources', '预置角色卡': 'Preset cards',
        '站内内置': 'Built-in', '推荐优先': 'Recommended', '按名称': 'By name', '按角色卡大小': 'By size',
        '最近聊过': 'Recently chatted', '按分组': 'By group', '添加顺序': 'Added order',
        '搜索角色卡': 'Search cards', '搜索角色名 / 作品 / 标签': 'Search name / work / tags',
        '搜索角色名 / 备注 / 分组': 'Search name / note / group', '搜索帖子': 'Search posts',
        '推荐': 'Recommended', '热门榜': 'Hot', '关注动态': 'Following', '我的收藏': 'Bookmarks',
        '我的主页': 'My profile', '私信': 'Direct messages', '论坛设置': 'Forum settings',
        '论坛角色': 'Forum characters', '发帖': 'New post', '最新回复': 'Latest reply',
        '最新发布': 'Newest', '热度': 'Popular', '浏览最多': 'Most viewed', '点赞最多': 'Most liked',
        '开场白': 'Opening message', '欢迎来到 My SW': 'Welcome to My SW',
        '查看使用文档': 'Read the docs', '先自己逛逛': 'Explore first', '关闭': 'Close',
        '选择分组': 'Choose group', '角色提示词 (System Prompt)': 'Character prompt (System Prompt)',
        '头像图片': 'Avatar image', '角色名字': 'Character name', '切换深色/浅色主题': 'Toggle dark / light theme',
        '回到短信': 'Back to messages', '角色列表': 'Character list', '分组': 'Group',
        '搜索角色名 / 备注 / 分组 ': 'Search name / note / group'
    };

    var TEXT_ORIG = new WeakMap();   // 文本节点 -> { zh, en }
    var ATTR_ORIG = new WeakMap();   // 元素 -> { attr: { zh, en } }
    var phraseTimer = 0;

    /* ---------------- 反向表：English → 中文 ----------------
       PHRASES 是「中文 → English」单向的，切回中文原本靠 WeakMap 记下原文再还原。
       但有些节点是派生出来的：设置面板的折叠标题，是在建组时把 h3 的文字 copy
       一份塞进 <summary>；如果那一刻界面正停英文，copy 出来的就是英文，WeakMap
       里没有这条记录，切回中文就永远回不去 —— 表现为「Plugins」压着一段中文说明。
       有反向表以后，凡是由本表产出的英文，任何时候都能被认回来（派生节点、
       重渲染出来的新节点、以及 localStorage 里存了英文标题的场景都覆盖）。 */
    var PHRASES_REV = {};
    function rebuildReverse() {
        var rev = {};
        Object.keys(PHRASES).forEach(function (zh) {
            var en = PHRASES[zh];
            if (!en || typeof en !== 'string') return;
            /* 多个中文短语可能共用一个英文（如「推荐」「推荐优先」）。
               先注册者优先，避免后写的把先写的顶掉造成来回跳变。 */
            if (Object.prototype.hasOwnProperty.call(rev, en)) return;
            rev[en] = zh;
        });
        PHRASES_REV = rev;
    }
    rebuildReverse();

    /* 用户产出的内容不做反向替换：聊天正文、角色提示词、帖子正文里
       出现一个和词条同名的英文单词，不该被改成中文。 */
    var CONTENT_SEL = '.message, .bubble, .chat-messages, [contenteditable="true"], textarea, '
        + '.forum-body, .post-body, .card-prompt, .prompt-preview, .memory-item, .ctx-summary-bubble';
    function inUserContent(p) {
        return !!(p && p.closest && p.closest(CONTENT_SEL));
    }

    function translateTextNodes(root) {
        if (!root) return;
        var nodes = [];
        if (root.nodeType === 3) {
            nodes = [root];            // 直接给一个文本节点（增量路径）
        } else {
            var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
            while (walker.nextNode()) nodes.push(walker.currentNode);
        }
        nodes.forEach(function (n) {
            var p = n.parentNode;
            if (!p || /^(SCRIPT|STYLE|TEXTAREA|CODE|PRE|INPUT)$/.test(p.nodeName)) return;
            /* 已经被 applyDocsEn 整块替换过的块：里面全是成品英文，
               再走短语替换只会把英文再"翻"一遍。
               data-no-i18n 是给「用户自己起的名字」留的免翻牌位：
               比如站点标识被改成「聊天」，那个词本来就在短语表里，
               有了这个标记就不会被翻成 Chat。 */
            if (p.closest && p.closest('[data-endone], [data-no-i18n]')) return;
            var raw = n.nodeValue;
            var entry = TEXT_ORIG.get(n);
            if (current === 'en') {
                // 已译过且节点内容仍是我们写入的译文 → 跳过
                if (entry && n.nodeValue === entry.en) return;
                var key = raw.trim();
                if (!key || !Object.prototype.hasOwnProperty.call(PHRASES, key)) return;
                var en = raw.replace(key, PHRASES[key]);
                TEXT_ORIG.set(n, { zh: raw, en: en });
                n.nodeValue = en;
            } else if (entry && n.nodeValue === entry.en) {
                n.nodeValue = entry.zh;
                TEXT_ORIG.delete(n);
                /* 漏网之鱼：记录丢了、但文字仍是本表产出的英文 */
            } else {
                var zhKey = raw.trim();
                if (!zhKey || inUserContent(p)) return;
                if (!Object.prototype.hasOwnProperty.call(PHRASES_REV, zhKey)) return;
                n.nodeValue = raw.replace(zhKey, PHRASES_REV[zhKey]);
                TEXT_ORIG.delete(n);
            }
        });
    }

    function translateAttrs(root) {
        if (!root || root.nodeType !== 1) return;
        var list = root.querySelectorAll('[placeholder],[title],[aria-label]');
        Array.prototype.forEach.call(list, function (node) {
            ['placeholder', 'title', 'aria-label'].forEach(function (attr) {
                if (!node.hasAttribute(attr)) return;
                var store = ATTR_ORIG.get(node) || {};
                var rec = store[attr];
                var val = node.getAttribute(attr);
                if (current === 'en') {
                    if (rec && val === rec.en) return;
                    var key = val.trim();
                    if (!key || !Object.prototype.hasOwnProperty.call(PHRASES, key)) return;
                    store[attr] = { zh: val, en: PHRASES[key] };
                    ATTR_ORIG.set(node, store);
                    node.setAttribute(attr, PHRASES[key]);
                } else if (rec && val === rec.en) {
                    node.setAttribute(attr, rec.zh);
                    delete store[attr];
                } else {
                    /* 与文本节点同因：派生出来的属性（title / placeholder 被
                       innerHTML 重建过）记录会丢，靠反向表认回中文。 */
                    var zhKey = val.trim();
                    if (!zhKey) return;
                    if (!Object.prototype.hasOwnProperty.call(PHRASES_REV, zhKey)) return;
                    node.setAttribute(attr, PHRASES_REV[zhKey]);
                    delete store[attr];
                }
            });
        });
    }

    function applyPhrases(root) {
        if (!root) return;
        translateTextNodes(root);
        translateAttrs(root);
    }

    function startPhraseObserver() {
        if (!window.MutationObserver || !document.body) return;
        var pendingRoots = [];
        new MutationObserver(function (records) {
            /* 英文、中文都要盯：中文这一侧盯的是「还没被反向还原的英文节点」，
               例如切回中文之后才建出来的折叠板标题。 */
            if (current !== 'en' && current !== 'zh') return;
            clearTimeout(phraseTimer);
            if (current === 'en') {
                phraseTimer = setTimeout(function () { applyPhrases(document.body); }, 150);
                return;
            }
            /* 中文侧是全量遍历会踩性能（聊天区每来一条消息都要重扫整页），
               只处理这次新插进来的子树。 */
            records.forEach(function (r) {
                Array.prototype.forEach.call(r.addedNodes, function (n) {
                    if (n.nodeType === 1 || n.nodeType === 3) pendingRoots.push(n);
                });
            });
            phraseTimer = setTimeout(function () {
                var roots = pendingRoots.splice(0);
                roots.forEach(function (n) {
                    if (!n.isConnected) return;
                    if (n.nodeType === 1) applyPhrases(n);
                    else if (n.parentNode) translateTextNodes(n);
                });
            }, 150);
        }).observe(document.body, { childList: true, subtree: true });
    }

    /* ---------------- 初始化 ---------------- */

    // 设置 → 更多 里的语言按钮:事件委托,页面任何时候都能点
    function syncLangButtons() {
        document.querySelectorAll('[data-si18n-setlang]').forEach(function (btn) {
            var on = btn.getAttribute('data-si18n-setlang') === current;
            btn.classList.toggle('active', on);
            btn.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
    }

    function bindLangButtons() {
        document.addEventListener('click', function (event) {
            var btn = event.target && event.target.closest ? event.target.closest('[data-si18n-setlang]') : null;
            if (!btn) return;
            setLang(btn.getAttribute('data-si18n-setlang'));
        });
    }

    function init() {
        bindLangButtons();
        injectStyle();
        applyDom();
        applyDom();
        if (pickerPending) showPicker();
        startPhraseObserver();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();

    window.SiteI18n = {
        t: t,
        getLang: function () { return current; },
        /**
         * 把一段已经翻译过的界面文本还原成登记过的中文原文（没登记就原样返回）。
         * 设置页的折叠分组表是按中文写的：用户先切英文再打开设置时，
         * 标题已经是英文，不做还原就一条都对不上，整页折叠会全失效。
         */
        zhOf: function (s) {
            var k = String(s == null ? '' : s).trim();
            return (k && Object.prototype.hasOwnProperty.call(PHRASES_REV, k)) ? PHRASES_REV[k] : k;
        },
        setLang: setLang,
        pickerNeeded: function () { return pickerPending; },
        afterPicker: afterPicker,
        showPicker: showPicker,
        applyDom: applyDom,
        applyDocsEn: applyDocsEn,
        /**
         * 追加注册界面短语(中文 -> English)。用于文件末尾的大批补全词条;
         * 注册后立即对当前页面重扫一遍,无需刷新即可生效。
         * @param {Object} map 形如 { '中文原文': 'English text' }
         * @returns {number} 实际合并的词条数
         */
        addPhrases: function (map) {
            if (!map) return 0;
            var added = 0;
            Object.keys(map).forEach(function (k) {
                if (k && typeof map[k] === 'string') { PHRASES[k] = map[k]; added++; }
            });
            rebuildReverse();   // 新词条也要进反向表，否则切回中文时认不回来
            if (document.body) applyPhrases(document.body);
            applyDocTitle();
            return added;
        },
        chunkText: chunkText,
        translateCard: translateCard,
        attachCardTranslate: attachCardTranslate
    };
})();

