    '和当前角色合作通关：火男孩怕水、水女孩怕火，两人都怕毒泥；石头能推能垫脚填坑，湖底压力钮开对方路上的门，升降台托人拿高台宝石。三种玩法：单人一人控俩（方向键 + WASD）、你和 AI 各控一个、或看 AI 双人演示。AI 的走路由本地 BFS 规划器实时计算（保证不送死），大模型只负责人设台词，API 挂了也能玩。': 'Beat the levels together with the current character: the fire boy fears water, the water girl fears fire, and both fear poison mud; rocks can be pushed and used as steps, pressure plates open doors on the partner’s path, and lifts raise you to high gems. Three ways to play: control both characters solo (arrow keys + WASD), you and the AI each control one, or watch an AI duo demo. The AI routes are computed in real time by a local BFS planner (it will not walk into death), and the language model only handles character lines — it still works if the API is down.',
    '：请到「设置 → 导入导出 → 加载 JS 文件设置」里勾选「森林冰火人」并刷新后，这个按钮才会生效。共三关，难度递进；宝石是加分项，不拿也能通关。想自己做关卡，再勾选「冰火人工坊」（同样默认不加载）：做好的关会出现在游戏的选关条里，也能导出成 JS 发给朋友。': ': enable Fireboy and Watergirl under Settings → Import/Export → JS file loading settings and refresh the page for this button to work. There are three levels of rising difficulty; gems are optional bonuses and you can finish without them. To build your own levels, also enable the Fireboy Workshop (also off by default): finished levels appear in the game’s level bar and can be exported as JS to share with friends.',
    '和当前角色下一盘。左边聊天（自带滚动条），中间棋盘，右边可以换棋盘大小、要提示、悔棋、再开一局或退出。新对局先抛硬币决定先手；落子由本地引擎计算候选点，AI 只从中挑一个并按自己的人设说话，所以它不会下出「被叫吃还去别处铺子」这种臭棋。围棋支持提子、打劫禁着点、禁止全局同形，终局可标记死子后数子。': 'Play a game with the current character: chat on the left (with its own scrollbar), the board in the middle, and controls on the right to change the board size, ask for hints, undo, start a new game or exit. A coin toss decides who moves first; the local engine computes candidate moves and the AI picks one while speaking in character, so it will not make absurd moves. Go supports captures, ko, no global repetition, and marking dead stones for scoring at the end.',
    '用的是当前聊天的角色和当前站点的模型（模型只负责在引擎给的候选点里挑一个并说话，API 挂了也能用本地引擎继续下）。开局前会先选棋盘大小：五子棋 13 / 15 / 19 路，围棋 9 / 13 / 19 路。没有打开角色、或当前是群聊时不能开始。': 'Uses the character of the current chat and the model of the current site (the model only picks a move from the engine’s candidates and talks; if the API is down, the local engine keeps the game going). Board size is chosen first: Gomoku 13 / 15 / 19, Go 9 / 13 / 19. You cannot start without an open character, or in a group chat.'
