    "提示词。适合核心世界观、重要人物关系等必须让 AI 时刻知道的设定。蓝灯条目可以不填关键词。": " prompt. Best for core worldbuilding and key relationships the AI must always know. Blue entries can skip keywords.",
    "：只有当关键词出现在最近 N 条消息中时才注入。适合不会每轮都用到的细节设定，": ": injected only when the keyword appears in the last N messages. Great for details you do not need every turn,",
