    "：开了「分段显示」时长回复会拆成多条气泡，回复刚落库时舞台会": ": with segmented display on, long replies split into several bubbles; the stage will",
    "（而不是末段），并且这一段会从第一页开始整段落定 —— 你在流式阶段已经读完的内容不会被打字机重新敲一遍，接着往后读即可。": " (not the final segment), and it settles as a whole from its first page — what you already read while streaming is not retyped, just keep reading.",
    "时切进舞台，会立刻接上已经出现的文字继续看，不用等这条回复说完。": " , stepping into the stage picks up the text already shown right away",
    "，也可设置全局背景兜底；还可以给某个情绪单独配一张背景（如「生气」时切到雷雨场景），情绪切换时背景会交叉淡入。": " , plus a global fallback background; a single emotion can also get its own background",
