window.SiteI18n && window.SiteI18n.addPhrases({
    "系统提示词拼好之后（世界书 / 记忆 / 时间之后，表情包说明之前）": "after the system prompt is assembled (after world book / memory / time, before sticker notes)",
    "在一轮对话里可能被多次调用，而重发、重新生成也会再走一遍。 追加内容前请先判断是否已包含，否则提示词会越叠越长：": "may be called several times in one conversation, and resends or regenerations run it again. Before appending, check whether the content is already included, or the prompt grows longer and longer:",
    "一次性补全，直接返回字符串。适合翻译、摘要、分类等场景。": "one-shot completion returning a string directly. Great for translation, summarization and classification.",
    "挂载， 系统会登记这个节点，在插件停用或权限被收回时自动移除，界面能干净复原。": "mount; the system registers the node and removes it automatically when the plugin is disabled or permissions are revoked, so the UI restores cleanly.",
    "：参数值存在插件记录里，改完要点卡片上的「保存参数」。读取时通过钩子的": ": parameter values live in the plugin record; after editing, click Save parameters on the card. Read them through the hook",
    "：插件不生效时，先看卡片上有没有黄色提示条（说明权限没给全），再看控制台有没有报错，最后确认": ": when a plugin does not work, first check for a yellow banner on its card (permissions incomplete), then the console for errors, and finally confirm",
    "：自己导入、或用 AI 写好再导入的插件，卡片上有「导出」。它导出的是当初保存下来的源码，不是运行后的状态。": ": for plugins you imported or generated with AI, the card has Export. It exports the source saved at import time, not the running state.",
    "位置在「设置 → 插件」，导入按钮下面有一块默认收起的折叠板「用 AI 编写插件」。": "It sits under Settings → Plugins; below the import button is a collapsed panel called Write a plugin with AI.",
    "（API + DOM 权限，把最后一条 AI 回复译成中文并弹出来）": "(API + DOM permissions; translates the latest AI reply into Chinese and pops it up)",
    "：用户可能切走角色、清空聊天、切到视觉小说模式，取元素时统一用可选链。": ": users may switch characters, clear the chat or enter visual novel mode, so always use optional chaining when grabbing elements.",
});

/* ============================================================
   界面短语补全 · 批次 42b:docs 好感度系统 段落
 */
window.SiteI18n && window.SiteI18n.addPhrases({
    "每完成一轮有效互动（你发出消息 → 角色成功回复）结算一次，计算公式为：": "settles once per effective exchange (you send a message → the character replies successfully); the formula is:",
    "：默认 0.85。档位越高涨得越慢 —— 调小它会让后期更难涨（更耐玩），调成 1 则每档速度一致。": ": default 0.85. Higher tiers grow more slowly - lower it to make the late game harder (more replay value); set it to 1 for a constant pace.",
    "：长期不聊会慢慢变淡。默认「1 天不聊后每天掉 1 点」，调成 0 即可完全关闭衰减。": ": long idle periods fade it. The default loses 1 point per day after 1 idle day; set it to 0 to disable decay entirely.",
    "：只想让某个角色涨快或涨慢时，单独给它设 0.1 ~ 3 的倍率。": ": to make one character rise faster or slower, give it an individual multiplier of 0.1 ~ 3.",
    "可以放下掩饰主动表达爱意，但仍保留角色本身的性格与底线": "may drop the pretense and express love openly, while keeping its own personality and limits",
    "。写得太笼统，角色可能一上来就越界；写得太保守，则会永远停在最拘谨的状态。 准则会随对话动态下发，所以改完保存，下一轮对话立刻生效。": ". Too vague and the character crosses the line on turn one; too conservative and they stay stiff forever. Guidelines ship with the dialogue, so saving applies from the next turn.",
    "面板里可以查看每个角色的进度与最近 10 条变化记录，也能手动 ±5 或重置。": "The panel shows each character progress and the last 10 changes, and lets you adjust by ±5 or reset.",
    "群聊中按「成员 × 用户」分别结算 —— 同一个群里，不同角色对你的亲近程度可以完全不同。": "In group chats, values settle per member × user - in the same group, different characters can feel very differently about you.",
});

/* ============================================================
   界面短语补全 · 批次 43:docs 插件指南 / 棋局 / 学习辅导 段落
 */
window.SiteI18n && window.SiteI18n.addPhrases({
    "插件运行在页面自己的上下文里，能力完全由你在「设置 → 插件 → 插件权限」授予。默认全部关闭； 只装自己看得懂代码的插件，是最实际的防线。": "Plugins run in the page’s own context, and their abilities are granted entirely by you under Settings → Plugins → Plugin permissions. Everything is off by default; installing only plugins whose code you can read is the most practical line of defense.",
    "文件，内容如下，然后在「设置 → 插件」里把这个文件导入即可：": " file with the content below, then import it under Settings → Plugins:",
    "。唯一标识，重复注册时后者覆盖前者。建议用短横线小写，如": ". A unique id; registering it again overwrites the previous one. Short lowercase with dashes is recommended, e.g.",
    "插件被停用或权限被收回时调用。必须在这里清理自己插入的元素，否则界面会留残影。": "Called when the plugin is disabled or a permission is revoked. Clean up your inserted elements here, or leftovers will stay on screen.",
    "：设置 → 插件 → 插件权限。默认关闭，关掉即对所有插件生效。": ": Settings → Plugins → Plugin permissions. Off by default; turning it off affects every plugin.",
    "本轮增量 = (基础增量 + 随机浮动 × random) × 档位衰减^当前档位序号 × 角色倍率 然后再受「每人每日上限」与「同一角色冷却时间」限制": "turn gain = (base gain + variance × random) × tier decay ^ tier index × character multiplier, then limited by the daily cap per person and the per-character cooldown",
    "有棋盘大小切换、提示、悔棋、再开一局、退出。围棋还多「弃权」和终局时的「结束并数子」。": "offers board-size switching, hints, undo, a new game and exit. Go adds Pass and, at the end, End and count.",
    "每一局开始都会抛硬币：正面你执黑、先下；反面角色执黑、先下，你执白。黑子先下，之后双方轮流。棋局使用当前聊天已经配置好的 API，不需要再单独填一份。": "Every game opens with a coin toss: heads, you play black and move first; tails, the character plays black and you take white. Black moves first, then you alternate. The game reuses the API already configured for the current chat — nothing extra to fill in.",
    "谁先把自己的五颗同色棋子连成一条直线(横、竖、斜均可),谁赢。": "Whoever lines up five stones of one color first — horizontally, vertically or diagonally — wins.",
    "棋盘可以在开局前选择 13 / 15 / 19 路,也可以在棋局右侧随时切换,切换会重开一局。": "Board size can be set to 13 / 15 / 19 lines before the game, or switched anytime from the right panel; switching starts a new game.",
    "每局开局先抛硬币:正面你执黑先下,反面角色执黑先下、你执白。": "Each game opens with a coin toss: heads, you play black and move first; tails, the character plays black and you take white.",
    "黑白轮流,在任意空交叉点落子。已有棋子的位置不能再下,点下去会抖动并提示「这里已经有子了」。": "Black and white alternate, playing on any empty intersection. Occupied points cannot be played; clicking one shakes and warns that a stone is already there.",
    "中间不能断开,也不能借用对方的棋子。只要有一方连成五子,棋局立即结束。": "The line cannot be interrupted, nor can it use the opponent’s stones. As soon as either side connects five, the game ends at once.",
    ":一条线上已有三颗且两端都是空位,叫「活三」,下一手就可能变成「活四」(两端都能成五)。一条线上已有四颗、只留一个空位,叫「冲四」,对方必须立刻堵住。": ": three stones in a line with both ends open form an open three, one move away from an open four (either end can become five). Four stones with a single open point form a four-threat that must be blocked immediately.",
    ":先看自己能不能一手连成五子;再看对方是否有四颗要成五,必须先堵;然后再考虑自己进攻(连三、连四)。": ": first check whether you can make five in one move; next, whether the opponent has four ready to become five and block; only then plan your own attack (threes and fours).",
    ":一手同时形成两个活三,或者「冲四 + 活三」,对方通常只能堵一边,这是最常见的取胜方式。": ": one move creating two open threes, or a four-threat plus an open three, usually leaves the opponent able to block only one side — the most common way to win.",
    "这里的围棋默认使用 9×9 的小棋盘,方便快速下完,也可以切换到 13 或 19 路。黑白轮流落子,目的不是连线,而是": "Go here defaults to a small 9×9 board for quick games, with 13 or 19 lines available. Black and white alternate; the goal is not to connect stones but to",
    "一颗棋子上、下、左、右紧挨着的空交叉点是它的「气」,斜角不算。相邻的同色棋子连成一块,整块共用这些气。": "The empty points directly above, below, left and right of a stone are its liberties; diagonals do not count. Adjacent stones of the same color form one group that shares them.",
    "把对方某一块棋的最后一口气堵住时,这一块会被整块提掉,对应位置变回空点。右侧会实时显示黑白各提了多少子。": "Filling the last liberty of an opponent group captures the whole group, and those points become empty. The right panel shows each side’s capture count live.",
    "落子后自己这一块没有气、又没有同时提掉对方的棋,这一手不能下。点到这种位置会提示「自杀或循环局面,不能下这里」。": "If your own group would have no liberties after the move without capturing anything, the move is illegal; such points warn that suicide or repetition is not allowed here.",
    "任何会让棋盘回到之前某个局面的落子都不允许,这样能避免双方无限循环。": "Any move that would return the board to a previous position is forbidden, preventing endless loops.",
    ":只在轮到你、且 AI 没有在思考时可用。引擎会在棋盘上标出它认为最好的一个点,并在聊天里说明,标记在你落子后自动消失。它只给建议,不会替你下。": ": available only on your turn and while the AI is not thinking. The engine marks its suggested point on the board and explains it in chat; the mark clears once you move. It only advises and will not play for you.",
    ":退回到上一步之前的局面,用来改掉一手误着。悔棋时提子数会一并恢复。": ": steps back one move so you can fix a misclick; capture counts are restored as well.",
    ":觉得没有更好的落点时,点「弃权」让手。双方连续弃权,就进入数子阶段。AI 也会在没有合适落点时弃权;如果 AI 连续两次弃权,同样直接进入数子阶段。": ": when no good point seems left, click Pass. If both sides pass in a row, counting begins. The AI also passes when it finds no good move, and two AI passes in a row likewise enter counting.",
    ":「再开一局」会重新抛硬币;「退出」回到普通聊天界面。如果有未结束的棋局被保存,界面会出现「放弃存档」按钮,点了之后该局无法恢复。": ": New game tosses the coin again; Exit returns to normal chat. If an unfinished game was saved, a Discard save button appears — once used, that game cannot be recovered.",
    "双方连续弃权后,棋盘上还没有提干净的棋子(即死子)必须先清掉,才能正确数子。进入这一阶段时,提示会说明「双方连续弃权,进入数子阶段」。": "After both sides pass in a row, dead stones not yet captured must be cleared before scoring. Entering this phase, a hint announces that counting has begun.",
    ":系统会先按保守规则猜一遍死子:只剩一口气的棋块,以及周围空地很小、没有做眼余地的棋块。这只是猜测,": ": the system makes a conservative first guess at dead stones — groups down to one liberty, and groups with too little room to make eyes. This is only a guess,",
    ":点击棋盘上的任意一块棋,可以在「死子」(棋子上出现金色叉)和「活子」之间切换,整块棋一起变化。": ": click any group on the board to toggle it between dead (a gold cross appears on the stones) and alive, changing the whole group together.",
    ":自己的活子数,加上被自己的棋完全包围的空点数。白棋自动加上": ": your living stones plus the empty points fully surrounded by your own stones. White automatically receives",
    ",用来抵消黑棋先下的优势;点数多的一方获胜,结果会显示在棋局状态里。": " to offset black’s first-move advantage; whoever scores more wins, and the result shows in the game status.",
    "围棋坐标使用棋迷习惯的写法:列用字母 A–T(跳过 I),行用数字,例如「D4」。棋盘大小的切换见上文。": "Go coordinates use the fan convention: letters A–T for columns (skipping I) and numbers for rows, e.g. “D4”. Board-size switching is described above.",
    "（点「打开学习辅导」进入全屏界面），是一个拍题讲解的「辅导老师」：拍一张题目照片（或直接输入文字、Ctrl+V 粘贴截图），AI 会像老师一样给你讲题。": " (click Open study tutor for the fullscreen view) is a homework tutor that walks through problems: snap a photo of the question (or type it, or paste a screenshot with Ctrl+V) and the AI explains it like a teacher.",
    "把解法拆成 3~6 步逐步揭示，看懂一步再点「下一步」，讲完可一键总结知识点&套路": "Reveals the solution in 3-6 steps, one at a time — click Next once you understand each step, then summarize key points & patterns in one click",
    "（清掉当前题目开始讲下一道；顶栏 ➕ 按钮也是同一个功能）。退出再进入时如果上次没讲完，会询问是否继续。": " (clears the current problem and starts the next; the ➕ button in the top bar does the same). Leaving mid-explanation and coming back asks whether to continue.",
    "「老师人设」可以换教学风格：默认辅导老师、温柔大姐姐、严格班主任、幽默段子手、猫娘老师，也可以完全自定义（名字 + 说话风格）。还可以": "The tutor persona changes the teaching style: default tutor, gentle big sister, strict homeroom teacher, funny joker or catgirl teacher — or fully custom (name plus speaking style). You can also",
    "：做过的题收进来，可按科目/学段筛选，支持直接从错题本把题再调出来重讲。": ": solved problems gather here, filterable by subject and school stage, and any problem can be pulled back out for another walkthrough.",
    "：讲过的题、知识点卡片会自动记一笔（本地完成，不额外消耗 API），老师「越用越懂你」。": ": explained problems and knowledge cards are logged automatically (locally, with no extra API usage), so the tutor knows you better over time.",
    "顶部可切换科目（可自定义增删）与学段/具体年级，界面顶部的科目、年级会随会话一起保存。": "Switch subject (editable) and school stage / grade at the top; the subject and grade shown in the top bar save with the session.",
    "下面这组模块把「酒馆（SillyTavern）」上常见、而本站原来缺少或较弱的能力补齐了。它们都是": "The modules below fill in capabilities that are common on SillyTavern but were missing or weak here. They are all",
});

