    "用户输入 / 斜杠命令 / AI 输出 / 世界书 / 提示词组装 / 聊天显示": "user input / slash commands / AI output / world book / prompt assembly / chat display",
    "。「AI 输出」会改写写入聊天记录的回复（持久生效）；「聊天显示」只改渲染、不动记录、不影响导出。替换串支持": ". \"AI output\" rewrites replies before they are stored (persists); \"chat display\" only changes rendering, never records or exports. Replacements support",
    "每条脚本可单独勾选参与哪些位置、调整执行顺序；面板带「试运行」与导入导出。典型用法：把": "Each script can opt into specific points and be reordered; the panel offers a test run plus import/export. Typical uses: collapsing",
    "折叠成文字、统一 Markdown 风格、自动清理模型多余的格式标签。入口：": " into text, unifying Markdown style, and cleaning extra format tags. Entry:",
    "每条消息气泡上有「译」按钮：点开看译文、再点收起；译文缓存在本机，重绘与刷新后自动恢复。引擎可选：": "A translate button on every message bubble: click to view, click again to collapse; translations cache locally and survive re-renders and refreshes. Engines:",
    "、不影响上下文与导出；这与「正则脚本 · AI 输出」位置有本质区别。入口：": ", without affecting context or exports; fundamentally different from the regex script AI output point. Entry:",
    "（放在对话历史之后，越靠近模型最后读到的位置服从性越高，适合「只用中文回答」这类硬约束）。": " (placed after the chat history — the closer to the last thing the model reads, the stricter the compliance; good for hard rules like \"answer in Chinese only\").",
    "正则不够用时，直接写一小段 JavaScript，在 用户输入 / 斜杠命令 / AI 输出 / 世界书 / 聊天显示 / 提示词组装 六个环节运行：": "When regex is not enough, write a bit of JavaScript that runs at six stages — user input / slash commands / AI output / world book / chat display / prompt assembly:",
    "即生效（什么都不 return = 不修改）；提示词组装环节直接拿到完整的 messages 数组。可以做条件逻辑、快捷指令、查表替换等复杂自动化。": " takes effect (returning nothing means no change); prompt assembly receives the full messages array. Enables conditionals, quick commands, table lookups and other automation.",
    "面板支持单条启用 / 排序 / 试运行 / 导入导出。": "The panel supports per-script enable / reorder / test run / import and export.",
    "；脚本以本页权限运行（等同 F12 控制台），请只粘贴你自己写的或可信来源的代码。入口：": "; scripts run with this page’s privileges (equivalent to the F12 console), so only paste code you wrote or trust. Entry:",
    "把当前对话拍一张命名快照（不切换、不改动任何内容），之后随时整体恢复；": "Takes a named snapshot of the current chat (no switching, no edits) that can be restored anytime;",
    "保留到那条消息为止、截断后面的内容，用来探索不同剧情走向。": " keeps everything up to that message and cuts the rest, to explore different plot directions.",
    "「恢复」与「分叉」执行前都会自动再存一张「自动快照」，误操作可以反悔；最多保留 20 个检查点，支持导出 / 导入 JSON。入口：消息操作栏，或": "Both Restore and Fork save an automatic snapshot first, so mistakes can be undone; up to 20 checkpoints are kept, with JSON export/import. Entry: the message action bar, or",
    "集中管理供 AI 参考的文本资料（世界观设定、术语表、写作规范等），按三种作用域自动装载：": "Manages reference texts for the AI (worldbuilding, glossary, writing rules) in one place, auto-loaded by three scopes:",
    "命中且启用的资料会在每轮请求发出前附加到系统提示词末尾（单轮注入上限 4000 字符，超出按顺序截断），不改聊天记录、不影响导出；支持整包导入导出。入口：": "Matched, enabled docs are appended to the system prompt before each request (max 4000 characters per turn, truncated in order), without touching chats or exports; whole-pack import/export supported. Entry:",
    "）即可出图，生成结果自动以图片消息附加到当前聊天；也可以到面板里手动生成并预览。支持四种后端：": ") to generate an image; results are attached to the current chat as image messages, or generate and preview manually in the panel. Four backends:",
