    "A：调大「最大上下文轮数」。但注意：上下文越大，每次消耗的 Token 越多、费用越高。": "A: Increase Max context rounds. But note: the bigger the context, the more tokens (and money) each request costs.",
    "A：可能是 Key 余额不足、模型名称写错、或平台风控拦截。检查 Key 对应平台的「用量」和「模型名是否含特殊前缀」。": "A: Possibly low balance, a wrong model name, or platform risk control. Check usage on the platform that issued the key, and whether the model name needs a special prefix.",
    "A：当前版本所有角色共享同一套 API 配置。如需为不同角色指定不同模型，可在使用中临时切换全局设置。": "A: All characters share one API config in the current version. To use different models per character, switch the global settings temporarily.",
    "A：支持。语音输入默认用浏览器原生识别，部分浏览器（如夸克）原生识别不可用；可在「设置 → AI 配置 → 语音转文字（STT）」配置 OpenAI 兼容的": "A: Yes. Voice input uses native browser recognition by default, which fails on some browsers (e.g. Quark); configure an OpenAI-compatible",
    "接口（如 whisper-1），配置后语音按钮会改为「录音 → 上传转文字」，保存后立即生效。AI 语音播报（TTS）在「AI 配置 → 高级 TTS」里配置。": " endpoint (e.g. whisper-1) under Settings → AI config → Speech to text (STT); the voice button then switches to record → upload → transcribe, effective after saving. TTS is configured under AI config → Advanced TTS.",
    "用你的 API 调用数据训练模型（详见各平台隐私政策）。本应用本身是纯前端应用，": "use your API data to train models (see each platform’s privacy policy). This app itself is fully front-end,",
    "按钮可切换深色 / 浅色主题。主题色在 CSS 变量中定义，高级用户可自行修改": " button toggles dark / light theme. Accent colors are defined as CSS variables for advanced users to customize",
