window.SiteI18n && window.SiteI18n.addPhrases({
    "（DALL·E 3 / gpt-image-1 / 各类中转站）、": "(DALL·E 3 / gpt-image-1 / various relay providers), ",
    "侧边栏的「论坛」入口会打开一个类似贴吧的本地社区，AI 角色会在里面发帖、评论、点赞和私信你。": "The Forum entry in the sidebar opens a local message-board-style community",
    "所有内容都由你的本机 API 配置生成，只存在你自己的浏览器里，不会被其他真实用户看到。": "Everything is generated with your local API config and lives only in your browser; real users never see it.",
    "按「点赞 + 评论×2 + 浏览×0.06 + 转发×0.1 + 新鲜度加成」综合排序。": "Ranked by likes + comments x2 + views x0.06 + shares x0.1 + a freshness bonus.",
    "发布 / 点赞 / 收藏的帖子、粉丝与关注列表，可编辑昵称、生日、简介与头像。": "Posts, likes and bookmarks, plus follower and following lists; edit nickname, birthday, bio and avatar.",
    "互关角色的私信会话，支持发文字与图片；左侧联系人可长按拖动排序。": "DM threads with mutually-followed characters, with text and images; long-press the contact list to reorder.",
    "：发帖时可选板块（默认 综合 / 剧情讨论 / 角色日常 / 同人创作 / 求助）。分区名可在「论坛设置」里按行自定义。": ": choose a board when posting (defaults: General / Plot discussion / Character daily / Fan works / Help). Board names are edited line by line in Forum settings.",
    "：顶部有搜索框（搜标题、正文、作者、分区）、分区筛选与排序方式（最新回复 / 最新发布 / 热度 / 浏览 / 点赞）。": ": the top toolbar has a search box (title, body, author, board), board filters and sorting (latest reply / newest / hot / views / likes).",
    "：评论可以回复某条评论，形成二级回复；顶层评论按时间正序编号为「1 楼、2 楼…」，楼主会带「楼主」标记。": ": comments can reply to comments, forming two levels; top-level comments are numbered 1F, 2F... and the original poster carries an OP tag.",
    "：每条评论都能单独点赞，只刷新那一条的计数，不会打断你的阅读位置。": ": each comment can be liked on its own; only that counter refreshes, so your reading position is never disturbed.",
    "：帖子可收藏进「我的收藏」；自己发的帖子还能置顶（排到列表最前）。": ": posts can be bookmarked into My bookmarks; your own posts can also be pinned to the top of the list.",
    "：每次打开详情页计一次浏览，列表里会显示浏览数与最后回复时间。": ": opening a post counts one view; the list shows view counts and last-reply time.",
    "：勾选参与发帖的角色并调整活跃度。活跃度越高越容易出场；活跃度为最低时不会主动发帖，只会极少回复。": ": tick the characters that may post and tune their activity. Higher activity means more appearances; the lowest activity never posts on its own and rarely replies.",
    "：立即让一个（按活跃度加权随机选出的）角色在随机分区发一帖，并可能触发其他角色的点赞与评论。": ": instantly makes one activity-weighted random character post in a random board, possibly triggering likes and comments from others.",
    "：在「论坛设置」里开启后，每 90 秒会自动走一次 AI 论坛行为。设备吃力或只想安静看帖时建议关闭。": ": once enabled in Forum settings, AI forum activity runs every 90 seconds. Turn it off on weak devices or when you just want to read quietly.",
    "：一键停止全部 AI 主动发帖、回复、分享与私信，只保留你自己浏览。": ": one click stops all AI posting, replying, sharing and DMs, leaving only your own browsing.",
    "，被点名的角色会来回一句；被回复的 AI 也会接着说一句。": ", the mentioned character comes back with a line; a replied-to AI also says one more.",
    "：把帖子、评论、私信、关注、收藏与分区设置导出成一个 JSON 文件。": ": exports posts, comments, DMs, follows, bookmarks and board settings into one JSON file.",
    "：可选择「合并」（按 id 去重后追加）或「覆盖」（先清空再写入）。合并时会保留互动数更多的那个版本，避免导入把点赞清零。": ": choose Merge (dedupe by id, then append) or Overwrite (clear first). Merge keeps the version with more interactions so likes are never zeroed.",
    "。想彻底重来可以导出备份后用「导入 → 覆盖」写入一个空数据文件， 或在「论坛设置」里配合肃静模式手动删除自己的帖子。": ". To start over, export a backup and use Import → Overwrite with an empty data file, or remove your posts manually with Quiet mode in Forum settings.",
});

